  vastus_med: ['muscle', 'Vastus medialis (VMO)', 'inner front-thigh muscle (quadriceps)', 'Inner quadriceps muscle forming the "teardrop" above the inner knee.', 'Straightens the knee and helps track the kneecap.', 'Weakness is linked to front-of-knee (patellofemoral) pain.'],
  biceps_fem: ['muscle', 'Biceps femoris', 'outer hamstring', 'Outer hamstring from the sit bone (and thigh bone) to the fibula head.', 'Bends the knee, straightens the hip.', 'The most commonly strained hamstring: sudden pain at the back of the thigh when sprinting.'],
  semi_tend_memb: ['muscle', 'Semitendinosus & semimembranosus', 'inner hamstrings', 'Inner hamstrings from the sit bone to the inner tibia.', 'Bend the knee, straighten the hip.', 'Back-of-thigh strains and inner-knee tendon pain.'],
