  deltoid_mid: ['muscle', 'Deltoid (middle)', 'side shoulder-cap muscle', 'Middle fibres from the acromion to the outer upper arm.', 'Raises the arm sideways.', 'Pain on the outer upper arm is often referred from the rotator cuff or bursa underneath.'],
  deltoid_post: ['muscle', 'Deltoid (posterior)', 'rear shoulder-cap muscle', 'Rear fibres from the shoulder blade spine to the upper arm.', 'Pulls the arm backward and turns it outward.', 'Back-of-shoulder ache with pulling or reaching behind.'],
