  brachioradialis: ['muscle', 'Brachioradialis', 'thumb-side forearm muscle', 'Muscle on the thumb side of the forearm, from the upper arm bone to the radius.', 'Bends the elbow, especially thumb-up.', 'Forearm ache from repetitive gripping or lifting.'],
  wrist_ext: ['muscle', 'Wrist & finger extensors (ECRL, ECRB, ED, ECU)', 'back-of-forearm muscles', 'Muscles on the back of the forearm starting from the outer elbow (lateral epicondyle).', 'Lift the wrist and straighten the fingers; steady the wrist when gripping.', 'Overuse causes outer elbow pain ("tennis elbow", mainly ECRB) and forearm ache.'],
