  fcu: ['muscle', 'Flexor carpi ulnaris', 'little-finger-side forearm muscle', 'Muscle along the little-finger side of the forearm; the ulnar nerve enters the forearm between its heads.', 'Bends the wrist toward the little-finger side.', 'Ulnar-side forearm pain; tightness can add to ulnar nerve irritation at the elbow.'],
  pronator_teres: ['muscle', 'Pronator teres', 'palm-down rotator', 'Short muscle across the upper front of the forearm.', 'Turns the palm down.', 'Can squeeze the median nerve (pronator syndrome): forearm ache and hand tingling.'],
