  thor_vert: ['bone', 'Thoracic vertebra', 'mid-back bone', 'One of the twelve mid-back vertebrae (T1–T12), each joined to a pair of ribs.', 'Support the trunk, anchor the ribs, protect the spinal cord.', 'Mid-back pain from facet/rib joints and posture; sudden pain with osteoporosis may be a compression fracture.'],
  lumb_vert: ['bone', 'Lumbar vertebra', 'low-back bone', 'One of the five large low-back vertebrae (L1–L5).', 'Carry most of the upper body\'s weight; allow bending.', 'Discs and facet joints here are the commonest sources of low back pain and sciatica.'],
  sacrum: ['bone', 'Sacrum', 'triangular base-of-spine bone', 'Triangular bone of five fused vertebrae wedged between the hip bones.', 'Transfers body weight from the spine to the pelvis.', 'Central low back/buttock pain; joins the pelvis at the sacroiliac joints.'],
  coccyx: ['bone', 'Coccyx', 'tailbone', 'Small fused bones at the very bottom of the spine.', 'Anchors pelvic floor muscles; takes weight when sitting back.', 'Coccydynia: pain when sitting, often after a fall or childbirth.'],
  ribs: ['bone', 'Ribs', 'rib bones', 'Twelve pairs of curved bones from the mid-back spine around the chest.', 'Protect the heart and lungs and move with breathing.', 'Rib joint irritation or fractures cause sharp pain with breathing, coughing or twisting.'],
  sternum: ['bone', 'Sternum', 'breastbone', 'Flat bone at the front of the chest joined to the ribs by cartilage.', 'Protects the heart; anchors ribs and collarbones.', 'Chest wall pain is common, but chest pain must first be checked for heart and lung causes.'],
